import csv
import io
import re
from collections import Counter


def parse_csv(raw_csv: str):
    def read_rows(text):
        stream = io.StringIO(text, newline="")
        try:
            return [list(row) for row in csv.reader(
                stream,
                delimiter=",",
                quotechar='"',
                doublequote=True,
                skipinitialspace=False,
                strict=False
            )]
        except csv.Error:
            rows = []
            buffer = ""
            for line in text.splitlines(True):
                buffer += line
                try:
                    parsed = list(csv.reader(
                        io.StringIO(buffer, newline=""),
                        delimiter=",",
                        quotechar='"',
                        doublequote=True,
                        strict=False
                    ))
                    if parsed:
                        rows.extend(parsed)
                        buffer = ""
                except csv.Error:
                    continue
            if buffer:
                rows.append([buffer.rstrip("\r\n")])
            return rows

    def normalized_row(row):
        return tuple(re.sub(r"\s+", " ", value.strip()).casefold() for value in row)

    date_re = re.compile(
        r"^\s*(?:\d{1,4}[-/.]\d{1,2}[-/.]\d{1,4}|"
        r"\d{1,2}\s+[A-Za-z]{3,12}\s+\d{2,4})\s*$"
    )
    time_re = re.compile(
        r"^\s*\d{1,2}:\d{2}(?::\d{2}(?:\.\d+)?)?"
        r"(?:\s*[AaPp][Mm])?(?:\s*[+-]\d{2}:?\d{2})?\s*$"
    )
    integer_re = re.compile(r"^\s*[+-]?\d+\s*$")
    number_re = re.compile(
        r"^\s*[\(\-+]?\s*(?:[$€£¥]\s*)?"
        r"(?:\d{1,3}(?:,\d{3})+|\d+)?(?:\.\d+)?"
        r"(?:\s*%)?\s*\)?\s*$"
    )
    url_re = re.compile(r"^\s*(?:https?|ftp)://", re.I)

    def value_kind(value):
        text = value.strip()
        if not text:
            return "empty"
        if url_re.match(text):
            return "url"
        if date_re.match(text):
            return "date"
        if time_re.match(text):
            return "time"
        if integer_re.match(text):
            return "integer"
        if number_re.match(text) and any(ch.isdigit() for ch in text):
            return "number"
        return "text"

    def header_score(row):
        if not row:
            return -1000
        score = 0
        nonempty = 0
        for value in row:
            text = value.strip()
            if not text:
                score -= 1
                continue
            nonempty += 1
            kind = value_kind(text)
            if kind == "text":
                score += 2
                if any(ch.isalpha() for ch in text):
                    score += 1
                if len(text) <= 40:
                    score += 1
                if len(text) > 80:
                    score -= 5
                if "\n" in text or "\r" in text:
                    score -= 2
            else:
                score -= 6
        if nonempty == 0:
            return -1000
        return score

    rows = read_rows(raw_csv)
    if rows and rows[0]:
        rows[0][0] = rows[0][0].lstrip("\ufeff")

    nonblank = [row for row in rows if any(value != "" for value in row)]
    if not nonblank:
        return {"columns": [], "rows": []}

    width_counts = Counter(len(row) for row in nonblank if len(row) > 1)
    if width_counts:
        expected_width = max(width_counts, key=lambda width: (width_counts[width], width))
    else:
        expected_width = max(len(row) for row in nonblank)

    width_rows = [
        (index, row) for index, row in enumerate(rows)
        if len(row) == expected_width and any(value != "" for value in row)
    ]

    if not width_rows:
        columns = ["column_" + str(index + 1) for index in range(expected_width)]
        output_rows = []
        for row in nonblank:
            fixed = list(row[:expected_width])
            fixed.extend([""] * (expected_width - len(fixed)))
            output_rows.append(fixed)
        return {"columns": columns, "rows": output_rows}

    normalized_counts = Counter(normalized_row(row) for _, row in width_rows)

    best_index = width_rows[0][0]
    best_header = width_rows[0][1]
    best_rank = -10**9
    for index, row in width_rows:
        base = header_score(row)
        repetitions = normalized_counts[normalized_row(row)]
        rank = base + (repetitions - 1) * expected_width * 5
        if rank > best_rank:
            best_rank = rank
            best_index = index
            best_header = row

    header_threshold = max(4, expected_width)
    header_parts = [(best_index, best_header)]

    previous_index = best_index - 1
    if previous_index >= 0:
        previous = rows[previous_index]
        if (
            len(previous) == expected_width
            and header_score(previous) >= header_threshold
            and normalized_row(previous) != normalized_row(best_header)
        ):
            header_parts.insert(0, (previous_index, previous))

    next_index = best_index + 1
    if next_index < len(rows):
        following = rows[next_index]
        if (
            len(following) == expected_width
            and header_score(following) >= header_threshold
            and normalized_row(following) != normalized_row(best_header)
        ):
            header_parts.append((next_index, following))

    if len(header_parts) > 1:
        columns = []
        for column_index in range(expected_width):
            pieces = []
            for _, part in header_parts:
                piece = re.sub(r"\s+", " ", part[column_index].strip())
                if piece and (not pieces or piece.casefold() != pieces[-1].casefold()):
                    pieces.append(piece)
            columns.append(" / ".join(pieces))
    else:
        columns = list(best_header)

    for index, value in enumerate(columns):
        if value == "":
            columns[index] = "column_" + str(index + 1)

    selected_header_norms = {
        normalized_row(part) for _, part in header_parts
    }
    primary_header_norm = normalized_row(best_header)

    def resembles_selected_header(row):
        if len(row) != expected_width:
            return False
        norm = normalized_row(row)
        if norm in selected_header_norms or norm == primary_header_norm:
            return True
        matches = 0
        considered = 0
        for left, right in zip(norm, primary_header_norm):
            if right:
                considered += 1
                if left == right:
                    matches += 1
        return considered > 0 and matches * 4 >= considered * 3 and header_score(row) >= header_threshold

    anchor_indices = []
    valid_data_rows = []
    for index, row in width_rows:
        if resembles_selected_header(row):
            continue
        if header_score(row) < header_threshold:
            anchor_indices.append(index)
            valid_data_rows.append(row)

    if not anchor_indices:
        for index, row in width_rows:
            if not resembles_selected_header(row):
                anchor_indices.append(index)
                valid_data_rows.append(row)

    if anchor_indices:
        first_data_index = min(anchor_indices)
        last_data_index = max(anchor_indices)
    else:
        first_data_index = 0
        last_data_index = len(rows) - 1

    profiles = []
    for column_index in range(expected_width):
        values = [
            row[column_index]
            for row in valid_data_rows
            if column_index < len(row)
        ]
        kinds = Counter(value_kind(value) for value in values)
        lengths = [len(value.strip()) for value in values if value.strip()]
        average_length = (
            sum(lengths) / float(len(lengths)) if lengths else 0.0
        )
        profiles.append((kinds, average_length, len(values)))

    def field_score(value, column_index):
        kinds, average_length, total = profiles[column_index]
        kind = value_kind(value)
        if total == 0:
            return 0.0

        common_kind = kinds.most_common(1)[0][0] if kinds else "text"
        score = 0.0
        if kind == common_kind:
            score += 6.0
        elif kinds.get(kind, 0):
            score += 2.0
        else:
            score -= 4.0

        if kind == "empty":
            empty_ratio = kinds.get("empty", 0) / float(total)
            score += 3.0 if empty_ratio >= 0.3 else -3.0
        elif average_length > 0:
            difference = abs(len(value.strip()) - average_length)
            score -= min(5.0, difference / (average_length + 4.0) * 3.0)
        return score

    def normalize_wide_row(row):
        extra = len(row) - expected_width
        best = None
        best_score_value = None
        for merge_at in range(expected_width):
            end = merge_at + extra + 1
            if end > len(row):
                continue
            candidate = (
                row[:merge_at]
                + [",".join(row[merge_at:end])]
                + row[end:]
            )
            if len(candidate) != expected_width:
                continue
            score = sum(
                field_score(candidate[index], index)
                for index in range(expected_width)
            )
            if best is None or score > best_score_value:
                best = candidate
                best_score_value = score
        return best if best is not None else row[:expected_width]

    def normalize_short_row(row):
        source_count = len(row)
        negative = -10**12
        scores = [[negative] * (source_count + 1) for _ in range(expected_width + 1)]
        paths = [[None] * (source_count + 1) for _ in range(expected_width + 1)]
        scores[0][0] = 0.0

        for column_index in range(expected_width):
            for used in range(source_count + 1):
                current = scores[column_index][used]
                if current <= negative / 2:
                    continue

                remaining_columns = expected_width - column_index
                remaining_values = source_count - used

                if remaining_values < remaining_columns:
                    blank_score = current + field_score("", column_index) - 1.0
                    if blank_score > scores[column_index + 1][used]:
                        scores[column_index + 1][used] = blank_score
                        paths[column_index + 1][used] = (used, "")

                if used < source_count:
                    consume_score = current + field_score(row[used], column_index)
                    if consume_score > scores[column_index + 1][used + 1]:
                        scores[column_index + 1][used + 1] = consume_score
                        paths[column_index + 1][used + 1] = (used, row[used])

        if scores[expected_width][source_count] <= negative / 2:
            result = list(row)
            result.extend([""] * (expected_width - len(result)))
            return result

        result = [""] * expected_width
        used = source_count
        for column_index in range(expected_width, 0, -1):
            path = paths[column_index][used]
            if path is None:
                break
            previous_used, value = path
            result[column_index - 1] = value
            used = previous_used
        return result

    output_rows = []
    for index, row in enumerate(rows):
        if not any(value != "" for value in row):
            continue
        if resembles_selected_header(row):
            continue

        if len(row) == expected_width:
            if first_data_index <= index <= last_data_index or header_score(row) < header_threshold:
                output_rows.append(list(row))
            continue

        if not (first_data_index <= index <= last_data_index):
            continue

        if len(row) > expected_width:
            output_rows.append(normalize_wide_row(list(row)))
        else:
            output_rows.append(normalize_short_row(list(row)))

    return {"columns": columns, "rows": output_rows}
